 2. Rust WASM Circom Engine (circomwasmmem.js → Rust)

circom_engine.zig – Natív Rust FFI:

zig
const std = @import("std");
const c = @cImport({
    @cInclude("circom_engine.h");  // Rust FFI header
});

pub const CircomEngine = struct {
    allocator: std.mem.Allocator,
    engine: ?*c.CircomEngine,

    pub fn init(allocator: std.mem.Allocator, 
                r1cs_path: []const u8,
                wasm_path: []const u8) !CircomEngine {
        const engine = c.circom_engine_init(
            r1cs_path.ptr,
            r1cs_path.len,
            wasm_path.ptr,
            wasm_path.len
        ) orelse return error.EngineInitFailed;

        return CircomEngine{
            .allocator = allocator,
            .engine = engine,
        };
    }

    /// Witness generálás (pure Zig arrays)
    pub fn computeWitness(self: *CircomEngine, 
                          input_signals: []const f32,
                          input_count: usize) ![]f32 {
        const witness = c.circom_compute_witness(
            self.engine,
            input_signals.ptr,
            input_count
        ) orelse return error.WitnessComputationFailed;

        const witness_len = c.circom_get_witness_length(self.engine);
        const witness_slice = self.allocator.alloc(f32, witness_len) catch unreachable;

        // Copy witness from C to Zig
        @memcpy(witness_slice.ptr, witness);
        c.circom_free_witness(witness);

        return witness_slice;
    }

    /// Proof generálás (Groth16)
    pub fn generateProof(self: *CircomEngine, 
                         witness: []const f32,
                         public_inputs: []const f32) !Proof {
        const proof_ptr = c.circom_generate_proof(
            self.engine,
            witness.ptr,
            witness.len,
            public_inputs.ptr,
            public_inputs.len
        ) orelse return error.ProofGenerationFailed;

        const proof = Proof{
            .pi_a = self.parseProofVector(proof_ptr.pi_a, 2),
            .pi_b = self.parseProofMatrix(proof_ptr.pi_b, 2, 2),
            .pi_c = self.parseProofVector(proof_ptr.pi_c, 2),
        };

        c.circom_free_proof(proof_ptr);
        return proof;
    }

    /// Batch proof verifikáció (több proof egyszerre)
    pub fn verifyProofsBatch(self: *CircomEngine,
                             proofs: []const Proof,
                             public_inputs: [][]const f32) ![]bool {
        const results = c.circom_verify_proofs_batch(
            self.engine,
            proofs.ptr,
            proofs.len,
            public_inputs.ptr,
            public_inputs.len
        ) orelse return error.VerificationFailed;

        const result_slice = self.allocator.alloc(bool, proofs.len) catch unreachable;
        for (0..proofs.len) |i| {
            result_slice[i] = (results[i] != 0);
        }

        c.circom_free_results(results);
        return result_slice;
    }
};


