 4. FormalVerificationEngine Integráció

zig
pub const FormalVerificationEngine = struct {
    allocator: std.mem.Allocator,
    circom_engine: CircomEngine,
    hoare_verifier: HoareLogicVerifier,
    proof_cache: std.AutoHashMap(u64, CircomProof),

    pub fn verifyInferenceStep(self: *FormalVerificationEngine,
                               input: []const f32,
                               expected_output: []const f32,
                               model_state: []const f32) !bool {

        // 1. Hash az input cache kulcsnak
        const input_hash = std.hash.Wyhash.hash(0, input);

        // 2. Cache lookup
        if (self.proof_cache.get(input_hash)) |cached_proof| {
            return self.verifyCachedProof(cached_proof, expected_output);
        }

        // 3. Új proof generálás
        const inputs = self.buildCircomInputs(input, model_state);
        defer self.allocator.free(inputs);

        const witness = try self.circom_engine.computeWitness(inputs, inputs.len);
        defer self.allocator.free(witness);

        const proof = try self.circom_engine.generateProof(
            witness,
            expected_output
        );

        // 4. Cache-ba rakás
        try self.proof_cache.put(input_hash, proof);

        // 5. Verifikáció
        return try self.circom_engine.verifyProof(proof, expected_output);
    }

    /// Batch verifikáció (több lépés egyszerre)
    pub fn verifyInferenceTrace(self: *FormalVerificationEngine,
                                trace: []const InferenceStep) ![]bool {
        var proofs = std.ArrayList(CircomProof).init(self.allocator);
        defer proofs.deinit();

        // Párhuzamos proof generálás
        const thread_pool = std.Thread.Pool.init(.{});
        defer thread_pool.deinit();

        try thread_pool.spawnLoop(.{}, generateProofsLoop, .{ 
            self, trace, &proofs 
        });

        // Batch verifikáció (1 hívás, N proof)
        const public_inputs = self.preparePublicInputs(trace);
        defer self.freePublicInputs(public_inputs);

        return try self.circom_engine.verifyProofsBatch(
            proofs.items,
            public_inputs
        );
    }
};




