// mmap() a WASM memória közvetlenül
pub fn mapCircomMemory(self: *CircomEngine, size: usize) ![]f32 {
    const mem_fd = c.circom_get_memory_fd(self.engine);
    const mapped = std.os.mmap(
        null,
        size * @sizeOf(f32),
        std.os.PROT.READ | std.os.PROT.WRITE,
        std.os.MAP.SHARED,
        mem_fd,
        0
    ) orelse return error.MmapFailed;

    return @as([*]f32, @alignCast(@ptrCast(mapped.ptr)))[0..size];
}


