        // Miller loop + Final exponentiation
        const lhs = self.millerLoop(a, b);
        const rhs = self.millerLoop(b, a);
        return lhs == rhs;
    }

    inline fn addSIMD(self: *BN254, a: [8]Fr, b: [8]Fr) [8]Fr {
        // AVX2 8-way parallel field addition
        comptime var result = [_]Fr{0} ** 8;
        @setRuntimeSafety(false);
        inline for (0..8) |i| {
            result[i] = a[i].add(b[i]);
        }
        return result;
    }
};




